use akita_error::AkitaError;
use std::{cell::RefCell, sync::Arc};

thread_local! {
    static HINTS: RefCell<Option<(Arc<[u64]>, usize)>> = const { RefCell::new(None) };
}

/// Install untrusted quartet hints. Each consumed code is authenticated against transcript ranks and signs.
///
/// Call [`finish_checked_hints`] after successful verification to require complete
/// consumption, or [`abort_checked_hints`] after a verification error. Both clear
/// the installed hints so the current thread can verify another proof.
pub fn install_checked_hints(bytes: &[u8]) -> Result<(), AkitaError> {
    if bytes.is_empty() || !bytes.len().is_multiple_of(8) {
        return Err(AkitaError::InvalidProof);
    }
    let words: Arc<[u64]> = if bytes.as_ptr().align_offset(8) == 0 {
        // Alignment and size were checked; u64 admits every initialized bit pattern.
        let words =
            unsafe { std::slice::from_raw_parts(bytes.as_ptr().cast::<u64>(), bytes.len() / 8) };
        words
            .iter()
            .map(|&x| u64::from_le(x))
            .collect::<Vec<_>>()
            .into()
    } else {
        bytes
            .chunks_exact(8)
            .map(|c| u64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect::<Vec<_>>()
            .into()
    };
    HINTS.with(|state| {
        let mut state = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?;
        if state.is_some() {
            return Err(AkitaError::InvalidProof);
        }
        *state = Some((words, 0));
        Ok(())
    })
}

/// Remove installed hints and reject unless every hint was consumed.
/// An incomplete session is cleared even when this returns an error.
pub fn finish_checked_hints() -> Result<(), AkitaError> {
    HINTS.with(|state| {
        let hints = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?
            .take();
        match hints {
            Some((words, used)) if used == words.len() => Ok(()),
            _ => Err(AkitaError::InvalidProof),
        }
    })
}

/// Discard hints after a failed verification. This does not authenticate the
/// hints or make the failed proof valid; it only releases the thread's session.
pub fn abort_checked_hints() -> Result<(), AkitaError> {
    HINTS.with(|state| {
        state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?
            .take();
        Ok(())
    })
}

pub(crate) fn active() -> bool {
    HINTS.with(|state| state.borrow().is_some())
}

pub(crate) fn take(count: usize) -> Result<(Arc<[u64]>, usize), AkitaError> {
    HINTS.with(|state| {
        let mut state = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?;
        let (words, used) = state.as_mut().ok_or(AkitaError::InvalidProof)?;
        let begin = *used;
        *used = begin
            .checked_add(count.checked_mul(4).ok_or(AkitaError::InvalidProof)?)
            .filter(|&end| end <= words.len())
            .ok_or(AkitaError::InvalidProof)?;
        Ok((Arc::clone(words), begin))
    })
}

pub(crate) fn validate(
    words: &[u64; 4],
    expected_one: u64,
    expected_two: u64,
    signs: u64,
) -> Result<(), AkitaError> {
    let (mut n1, mut n2, mut r1, mut r2, mut s1, mut s2) = (0usize, 0usize, 0u64, 0u64, 0u64, 0u64);
    for q in 0..16 {
        let code = ((words[q / 4] >> (10 * (q % 4))) & 1023) as usize;
        let meta = *META.get(code).ok_or(AkitaError::InvalidProof)?;
        let a = (meta & 7) as usize;
        let b = ((meta >> 3) & 7) as usize;
        if n1 + a > 31 || n2 + b > 10 || 4 * (q + 1) - (n1 + a) > 33 {
            return Err(AkitaError::InvalidProof);
        }
        let free = 4 * q - n1;
        r1 += RANK_ONE[(q * 32 + n1) * 16 + ((meta >> 6) & 15) as usize];
        r2 += RANK_TWO[(free * 11 + n2) * 16 + ((meta >> 10) & 15) as usize];
        s1 |= ((meta >> 14) & 15) << n1;
        s2 |= ((meta >> 18) & 15) << n2;
        n1 += a;
        n2 += b;
    }
    if n1 != 31
        || n2 != 10
        || r1 != expected_one
        || r2 != expected_two
        || (s1 | (s2 << 31)) != signs
    {
        return Err(AkitaError::InvalidProof);
    }
    Ok(())
}
