#[cfg(test)]
mod authentication_tests {
    use super::*;
    #[test]
    fn compact_quartets_bind_magnitudes_positions_and_signs() {
        // The first 31 positions have coefficient -1, then ten have -2.
        // Both colex subsets start at zero and therefore have rank zero.
        let mut words = [0u64; 4];
        for q in 0..16 {
            let mut code = 0u64;
            for i in (0..4).rev() {
                let position = 4 * q + i;
                let digit = if position < 31 {
                    1
                } else if position < 41 {
                    0
                } else {
                    2
                };
                code = 5 * code + digit;
            }
            words[q / 4] |= code << (10 * (q % 4));
        }
        validate(&words, 0, 0, (1u64 << 41) - 1).unwrap();
        assert!(validate(&words, 0, 0, 0).is_err());
        words[0] = (words[0] & !1023) | 1023;
        assert!(validate(&words, 0, 0, (1u64 << 41) - 1).is_err());
    }
}
